dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": [
        {
          "label": "Systemic lupus erythematosus",
          "value": "SLE"
        }
      ]
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "European",
          "value": "eu"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "global_associations",
      "header": "Genome-wide significant single-variant associations",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "global-associations",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Position(CHR:POS)",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "join multi",
            "field name": "Allele(REF:ALT)",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": [
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "dbSNP",
            "raw field": "dbSNP"
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "array to string",
            "field name": "Closest Genes",
            "raw field": "nearest",
            "separate by": ","
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          }
        ],
        "top rows": [
          "Position(CHR:POS)",
          "Allele(REF:ALT)",
          "dbSNP",
          "Consequence",
          "Closest Genes",
          "P-Value",
          "Beta"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ]
          },
          "Beta": {
            "type": [
              "fixed 4",
              "direction triangle"
            ]
          }
        }
      }
    },
    {
      "section id": "gene_finder",
      "header": "Top common variant gene-level associations with p-value ≤ 0.05",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "gene-finder",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "-Log10(p)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Samples",
            "raw field": "subjects"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          }
        ],
        "top rows": [
          "Gene",
          "P-Value",
          "Samples"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ]
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "parameter": "pValue",
          "type": "search lower than"
        }
      ],
      "visualizer": {
        "label": "",
        "type": "manhattan bitmap plot",
        "x axis field": "Region",
        "y axis field": "-Log10(p)",
        "render by": "Gene",
        "y axis label": "-Log10(p)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value"
        ],
        "height": 150
      }
    },
    {
      "section id": "pathway_associations",
      "header": "Top pathways with p-value ≤ 0.05",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "pathway-associations",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Pathway",
            "raw field": "pathwayName"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Standard error",
            "raw field": "stdErr"
          }
        ],
        "top rows": [
          "Pathway",
          "P-Value",
          "Beta",
          "Standard error"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ]
          },
          "Beta": {
            "type": [
              "fixed 4",
              "direction triangle"
            ]
          },
          "Standard error": {
            "type": [
              "fixed 4"
            ]
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "parameter": "pValue",
          "type": "search lower than"
        }
      ]
    },
    {
      "section id": "genetic_correlation",
      "header": "Genetically correlated phenotypes",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "genetic-correlation",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "other_phenotype"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Correlation",
            "raw field": "rg"
          },
          {
            "type": "raw",
            "field name": "Standard error",
            "raw field": "stdErr"
          }
        ],
        "top rows": [
          "Phenotype",
          "P-Value",
          "Correlation",
          "Standard error"
        ],
        "column formatting": {
          "Phenotype": {
            "type": [
              "kp phenotype link"
            ],
            "link to": "/phenotype.html?phenotype=",
            "new tab": "true"
          },
          "P-Value": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ]
          },
          "Correlation": {
            "type": [
              "fixed 4"
            ]
          },
          "Standard error": {
            "type": [
              "fixed 4"
            ]
          }
        }
      }
    },
    {
      "section id": "global_enrichment",
      "header": "Globally enriched annotations",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "global-enrichment",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "SNPs",
            "raw field": "SNPs"
          },
          {
            "type": "raw",
            "field name": "Expected SNPs",
            "raw field": "expectedSNPs"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "P-Value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "calculate",
            "field name": "Fold",
            "expression": [
              "SNPs",
              "/",
              "expectedSNPs"
            ],
            "calculation type": "math"
          },
          {
            "type": "calculate",
            "field name": "Test",
            "expression": [
              "(",
              "SNPs",
              "/",
              "expectedSNPs",
              ")",
              "*",
              "pValue"
            ],
            "calculation type": "math"
          }
        ],
        "top rows": [
          "Tissue",
          "Annotation",
          "Ancestry",
          "P-Value",
          "Fold"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Fold": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "visualizer": {
        "type": "scatter plot",
        "render type": "single plot",
        "group by": "Annotation",
        "color by": "Annotation",
        "y axis field": "Fold",
        "y axis label": "Fold (SNPs/expectedSNPs)",
        "x axis field": "P-Value(-log10)",
        "x axis label": "-Log10(p-value)",
        "ticks decimal point": "2",
        "render by": "Tissue",
        "hover content": [
          "Annotation",
          "P-Value",
          "Expected SNPs",
          "SNPs",
          "Fold"
        ],
        "height": 120,
        "width": 200,
        "plot margin": {
          "left": 60,
          "right": 20,
          "top": 40,
          "bottom": 50,
          "bump": 5
        }
      },
      "filters": [
        {
          "field": "Ancestry",
          "label": "Ancestry",
          "type": "checkbox"
        },
        {
          "field": "Annotation",
          "label": "Annotation",
          "type": "checkbox"
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        }
      ]
    }
  ]
}
